def solve():
    # We need to find the smallest positive integer n such that
    # r^3 + (n-r)^3 = 2007 * n for some integer r, 0 <= r <= n.

    N_target = 2007

    # Upper bound check: r^3 + (n-r)^3 >= n^3 / 4.
    # 2007 * n >= n^3 / 4  => 8028 >= n^2 => n <= sqrt(8028) approx 89.6
    max_n = 90 

    for n in range(1, max_n):
        # We check r from 0 up to n // 2 due to symmetry.
        for r in range(n // 2 + 1):
            if r == 0:
                LHS = n**3
            else:
                LHS = r**3 + (n - r)**3

            RHS = N_target * n

            if LHS == RHS:
                print(f"Found solution: n = {n}, r = {r}")
                return n, r

    return None, None

